export const categories = [...new Set(products.map((p) => p.category))];

export function getProductsByCategory(category: string): ProductData[] {
  return products.filter((p) => p.category === category);
}

export function getProductBySlug(slug: string): (ProductData & { slug: string }) | undefined {
  const product = products.find(
    (p) => slugify(p.name + "-" + p.billCode) === slug
  );
  if (!product) return undefined;
  return { ...product, slug: slugify(product.name + "-" + product.billCode) };
}
